export const Navbar = ({ route, navigate, theme, toggleTheme }) => {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  useEffect(() => { const onScroll = () => setScrolled(window.scrollY > 20); onScroll(); window.addEventListener('scroll', onScroll, { passive: true }); return () => window.removeEventListener('scroll', onScroll); }, []);
  const go = (r) => { navigate(r); setOpen(false); };
  
  // Fix: Padding Navbar di mobile diperkecil agar tidak makan layar
  return (
    <header className={classNames('fixed inset-x-0 top-0 z-[80] transition-all duration-300', scrolled ? 'py-2 sm:py-4' : 'py-4 sm:py-6')}>
      <div className="mx-auto max-w-7xl px-3 sm:px-6">
        <div className={classNames('flex items-center justify-between rounded-2xl sm:rounded-3xl px-4 py-2.5 sm:px-6 sm:py-3 transition-all duration-300', scrolled ? 'glass dark:glass shadow-xl' : 'bg-white/50 dark:bg-[#030F26]/30 backdrop-blur-md')}>
          <Logo onClick={() => go(ROUTES.HOME)} />
          <nav className="hidden items-center gap-2 lg:flex">
            {NAV_LINKS.map((link) => (
              <button key={link.route} onClick={() => go(link.route)} className={classNames('rounded-xl px-4 py-2 text-sm font-bold transition-all', route === link.route ? 'bg-[#1566D1] text-white shadow-md' : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900 dark:text-slate-300 dark:hover:bg-white/10 dark:hover:text-white')}>
                {link.label}
              </button>
            ))}
          </nav>
          <div className="flex items-center gap-1 sm:gap-3">
            <button onClick={() => go(ROUTES.ADMIN)} className="hidden md:inline-flex rounded-xl p-2 sm:p-2.5 text-slate-500 transition hover:bg-[#1566D1]/10 hover:text-[#1566D1] dark:text-slate-400 dark:hover:bg-white/10 dark:hover:text-white"><ShieldCheck className="h-5 w-5" /></button>
            <button onClick={toggleTheme} className="rounded-xl p-2 sm:p-2.5 text-slate-500 transition hover:bg-slate-100 hover:text-slate-900 dark:text-slate-400 dark:hover:bg-white/10 dark:hover:text-white">
              {theme === 'dark' ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}
            </button>
            {/* Fix: Pastikan tombol ini hilang di layar HP (hidden md:inline-flex) */}
            <Button size="sm" className="hidden md:inline-flex" onClick={() => go(ROUTES.CONTACT)}>Hubungi Kami</Button>
            <button onClick={() => setOpen((o) => !o)} className="rounded-xl p-2 sm:p-2.5 text-slate-700 transition hover:bg-slate-100 dark:text-white dark:hover:bg-white/10 lg:hidden">
              {open ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
        {open && (
          <>
            <div className="fixed inset-0 -z-10 bg-slate-900/20 backdrop-blur-sm dark:bg-black/60 lg:hidden" onClick={() => setOpen(false)} />
            <div className="mt-4 rounded-3xl glass dark:glass p-4 shadow-2xl lg:hidden max-h-[75vh] overflow-y-auto">
              <nav className="flex flex-col gap-2">
                {NAV_LINKS.map((link) => (
                  <button key={link.route} onClick={() => go(link.route)} className={classNames('rounded-2xl px-5 py-3.5 text-left text-sm font-bold transition-colors', route === link.route ? 'bg-[#1566D1] text-white' : 'text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-white/5')}>
                    {link.label}
                  </button>
                ))}
                <div className="mt-4 pt-4 border-t border-slate-200 dark:border-white/10 flex flex-col gap-3">
                  <Button className="w-full h-12" onClick={() => go(ROUTES.CONTACT)}>Hubungi Kami</Button>
                  <button onClick={() => go(ROUTES.ADMIN)} className="flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-100 dark:bg-white/5 h-12 text-sm font-bold text-slate-600 dark:text-slate-300 transition hover:bg-[#1566D1]/10 hover:text-[#1566D1] dark:hover:text-white">
                    <ShieldCheck className="h-5 w-5" /> Akses Admin
                  </button>
                </div>
              </nav>
            </div>
          </>
        )}
      </div>
    </header>
  );
};

