const TestimonialCarousel = ({ testimonials }) => {
  const approved = testimonials.filter((t) => t.status === 'approved');
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  useEffect(() => {
    if (paused || approved.length <= 1) return;
    const timer = setInterval(() => setIndex((i) => (i + 1) % approved.length), 6000);
    return () => clearInterval(timer);
  }, [paused, approved.length]);
  if (!approved.length) return null;
  const active = approved[index];
  return (
    <section className="relative py-24">
      <div className="mx-auto max-w-5xl px-4 sm:px-6">
        <SectionHeading eyebrow="Kredibilitas" title="Dipercaya oleh Klien" />
        <div className="relative mt-12" onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}>
          <GlassCard hover={false} className="text-center sm:p-12 shadow-2xl border border-[#1566D1]/20">
            <Quote className="mx-auto mb-6 h-12 w-12 text-[#1566D1]/20" />
            <p className="text-xl leading-relaxed text-slate-800 dark:text-slate-200 sm:text-2xl font-medium">“{active.content}”</p>
            <div className="mt-10 flex flex-col items-center gap-4">
              {active.client_photo_url && <img src={active.client_photo_url} alt={active.client_name} className="h-16 w-16 rounded-full border-4 border-white dark:border-[#030F26] shadow-md object-cover" />}
              <div>
                <p className="font-bold text-slate-900 dark:text-white">{active.client_name}</p>
                <p className="text-sm font-bold text-[#1566D1] dark:text-[#7fb0f5] mt-1">{active.client_title}{active.client_company ? ` di ${active.client_company}` : ''}</p>
              </div>
              <StarRating value={active.rating} />
            </div>
          </GlassCard>
          <div className="mt-8 flex items-center justify-center gap-2">
            {approved.map((_, i) => <button key={i} onClick={() => setIndex(i)} className="p-2 outline-none"><span className={classNames('block h-2 rounded-full transition-all duration-300', i === index ? 'w-8 bg-[#1566D1]' : 'w-2 bg-slate-300 dark:bg-slate-700')} /></button>)}
          </div>
        </div>
      </div>
    </section>
  );
};

