export const PortfolioPage = ({ data, navigate }) => {
  const [category, setCategory] = useState('Semua');
  const [search, setSearch] = useState('');
  const [debounced, setDebounced] = useState('');
  const [visibleCount, setVisibleCount] = useState(6);
  useEffect(() => { const t = setTimeout(() => setDebounced(search), 300); return () => clearTimeout(t); }, [search]);
  const published = data.portfolios.filter((p) => p.is_published);
  const filtered = useMemo(() => published.filter((p) => (category === 'Semua' || p.category === category) && (!debounced.trim() || p.title.toLowerCase().includes(debounced.toLowerCase().trim()) || (p.client_name || '').toLowerCase().includes(debounced.toLowerCase().trim()))), [published, category, debounced]);
  const visible = filtered.slice(0, visibleCount);
  return (
    <>
      <PageHero eyebrow="Karya Kami" title="Arsip Proyek Digital" description="Eksplorasi implementasi rekayasa perangkat lunak dan desain antarmuka canggih dari berbagai industri." />
      <section className="py-8">
        <div className="mx-auto max-w-7xl px-4 sm:px-6">
          <GlassCard className="sticky top-28 z-30 mb-12 flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between !p-5" hover={false}>
            <div className="flex flex-wrap gap-2">
              {PORTFOLIO_CATEGORIES.map((c) => (<button key={c} onClick={() => { setCategory(c); setVisibleCount(6); }} className={classNames('rounded-xl px-4 py-2 text-sm font-bold transition-all duration-300', category === c ? 'bg-[#1566D1] text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700')}>{c}</button>))}
            </div>
            <div className="relative w-full sm:w-72">
              <Search className="pointer-events-none absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-slate-400" />
              <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Cari proyek atau klien..." className={classNames(inputClass, 'pl-12')} />
            </div>
          </GlassCard>
          {visible.length ? (
            <div className="grid gap-8 sm:grid-cols-2 lg:grid-cols-3">
              {visible.map((p, i) => <PortfolioCard key={p.id} item={p} navigate={navigate} delay={(i % 3) * 80} />)}
            </div>
          ) : (<div className="mt-12"><EmptyState icon={Search} title="Proyek tidak ditemukan" description="Coba gunakan kategori atau kata kunci pencarian yang lain." /></div>)}
          {visibleCount < filtered.length && <div className="mt-16 text-center"><Button variant="outline" onClick={() => setVisibleCount((c) => c + 6)} icon={Plus}>Muat Lebih Banyak Karya</Button></div>}
        </div>
      </section>
      <CtaSection navigate={navigate} />
    </>
  );
};

