        <div className="mx-auto max-w-5xl px-4 sm:px-6">
          <Reveal>
            <div className="mx-auto overflow-hidden rounded-[2rem] bg-slate-100 dark:bg-slate-800 shadow-2xl" style={{ maxWidth: item.category === 'Mobile App' ? '400px' : '100%' }}>
              <img src={gallery[activeImage]} alt={item.title} className={classNames('w-full object-cover', item.category === 'Mobile App' ? 'aspect-[4/5]' : 'aspect-video')} />
