                <div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#1566D1]/10 text-[#1566D1]"><Calendar className="h-5 w-5" /></div><span className="font-bold text-slate-900 dark:text-white">{formatDate(item.completed_at)}</span></div>
