        {title && <h2 className="mb-10 text-center text-3xl font-black tracking-tight text-slate-900 dark:text-white sm:text-4xl">{title}</h2>}
        <div className="space-y-4">
          {items.map((item) => <FaqAccordionItem key={item.id} item={item} open={openId === item.id} onToggle={() => setOpenId((id) => (id === item.id ? null : item.id))} />)}
        </div>
      </div>
    </section>
  );
};

export const FaqPage = ({ data, navigate }) => {
  const published = data.faq_items.filter((f) => f.is_published);
  const categories = ['Semua', ...Array.from(new Set(published.map((f) => f.category).filter(Boolean)))];
  const [category, setCategory] = useState('Semua');
  const [search, setSearch] = useState('');
  const [openId, setOpenId] = useState(null);
  const filtered = published.filter((f) => (category === 'Semua' || f.category === category) && (!search.trim() || f.question.toLowerCase().includes(search.toLowerCase().trim()) || f.answer.toLowerCase().includes(search.toLowerCase().trim())));
  return (
    <>
      <PageHero eyebrow="Knowledge Base" title="Pertanyaan Umum" description="Temukan jawaban mendetail terkait operasional dan prosedur layanan teknis kami." />
      <section className="py-12">
        <div className="mx-auto max-w-3xl px-4 sm:px-6">
          <div className="relative mb-8"><Search className="pointer-events-none absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-slate-400" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Cari topik yang ingin Anda ketahui..." className={classNames(inputClass, 'pl-12 !rounded-2xl !h-14 shadow-sm')} /></div>
          <div className="mb-10 flex flex-wrap justify-center gap-2">
            {categories.map((c) => <button key={c} onClick={() => setCategory(c)} className={classNames('rounded-xl px-4 py-2 text-sm font-bold transition-all', category === c ? 'bg-[#1566D1] text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700')}>{c}</button>)}
          </div>
          {filtered.length ? <div>{filtered.map((item) => <FaqAccordionItem key={item.id} item={item} open={openId === item.id} onToggle={() => setOpenId((id) => (id === item.id ? null : item.id))} />)}</div> : <EmptyState icon={HelpCircle} title="Informasi tidak ditemukan." />}
        </div>
      </section>
      <CtaSection navigate={navigate} />
    </>
  );
};

export const ContactPage = ({ data, crud }) => {
  const toast = useToast();
  const settings = data.site_settings;
  const empty = { full_name: '', email: '', whatsapp: '', company: '', service_interest: '', budget_range: '', message: '' };
  const [form, setForm] = useState(empty);
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const setField = (key, value) => { setForm((f) => ({ ...f, [key]: value })); setErrors((e) => ({ ...e, [key]: undefined })); };
  const validate = () => {
    const e = {};
    if (!form.full_name.trim()) e.full_name = 'Identitas wajib diisi';
    if (!form.email.trim()) e.email = 'Email wajib diisi'; else if (!isValidEmail(form.email)) e.email = 'Format email tidak sesuai';
    if (!form.message.trim()) e.message = 'Deskripsi proyek wajib diisi';
    setErrors(e); return Object.keys(e).length === 0;
  };
  const handleSubmit = async (ev) => {
    ev.preventDefault(); if (!validate()) return; setSubmitting(true);
    try { await crud.leads.create({ ...form, status: 'new', source_page: 'contact', created_at: new Date().toISOString() }); setSubmitted(true); setForm(empty); toast?.success('Data berhasil masuk ke sistem kami.'); } 
    catch { toast?.error('Gagal mengirim formulir.'); } 
    finally { setSubmitting(false); }
  };

  const contactItems = [
    { icon: Mail, label: 'Email Resmi', value: settings.contact_email || BRAND.email, copy: settings.contact_email || BRAND.email },
    { icon: Phone, label: 'Jalur WhatsApp', value: `+${settings.whatsapp_number || BRAND.whatsapp}`, copy: settings.whatsapp_number || BRAND.whatsapp },
    { icon: MapPin, label: 'Alamat Operasional', value: settings.address || BRAND.address },
    { icon: Clock, label: 'Jam Kerja', value: settings.operating_hours || BRAND.hours },
  ];

  return (
    <>
      <PageHero eyebrow="Kontak Terpadu" title="Mari Eksekusi Ide Anda" description="Isi form briefing di bawah ini. Tim analis teknis kami akan merespons dalam 1×24 jam kerja." />
      <section className="py-12">
        <div className="mx-auto grid max-w-7xl gap-8 px-4 sm:px-6 lg:grid-cols-5">
          <div className="lg:col-span-2">
            <Reveal>
              <div className="space-y-4">
                {contactItems.map((c) => (
                  <GlassCard key={c.label} hover={false} className="flex items-center gap-4 !p-5">
                    <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-[#1566D1]/10 text-[#1566D1]"><c.icon className="h-5 w-5" /></div>
                    <div className="min-w-0 flex-1"><p className="text-xs font-bold uppercase tracking-widest text-slate-400">{c.label}</p><p className="mt-1 truncate font-bold text-slate-900 dark:text-white">{c.value}</p></div>
                    {c.copy && <button onClick={async () => { (await copyToClipboard(c.copy)) && toast?.info('Tersalin ke clipboard'); }} className="rounded-xl p-2.5 text-slate-400 transition hover:bg-slate-100 hover:text-[#1566D1] dark:hover:bg-slate-800 dark:hover:text-white"><Copy className="h-5 w-5" /></button>}
                  </GlassCard>
                ))}
                <a href={buildWhatsAppLink(settings.whatsapp_number)} target="_blank" rel="noreferrer" className="block mt-6"><Button className="w-full bg-[#25D366] hover:bg-[#1DA851] text-white border-none" icon={MessageCircle} size="lg">Konsultasi via WhatsApp</Button></a>
              </div>
            </Reveal>
          </div>
          <div className="lg:col-span-3">
            <Reveal delay={120}>
              <GlassCard hover={false} className="h-full">
                {submitted ? (
                  <div className="flex h-full flex-col items-center justify-center py-16 text-center">
                    <div className="mb-6 flex h-20 w-20 items-center justify-center rounded-full bg-emerald-500/10 text-emerald-500"><CheckCircle2 className="h-10 w-10" /></div>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white">Briefing Diterima</h3>
                    <p className="mt-3 max-w-sm text-base font-medium text-slate-500 dark:text-slate-400">Dokumen briefing proyek Anda telah masuk ke dalam antrean analisis tim Viska Labs.</p>
                    <Button className="mt-8" variant="outline" onClick={() => setSubmitted(false)}>Kirim Briefing Baru</Button>
                  </div>
                ) : (
                  <form onSubmit={handleSubmit}>
                    <fieldset disabled={submitting} className="space-y-6">
                      <div className="grid gap-6 sm:grid-cols-2"><Field label="Nama Lengkap" required error={errors.full_name}><Input value={form.full_name} onChange={(e) => setField('full_name', e.target.value)} placeholder="John Doe" /></Field><Field label="Alamat Email" required error={errors.email}><Input type="email" value={form.email} onChange={(e) => setField('email', e.target.value)} placeholder="john@perusahaan.com" /></Field></div>
                      <div className="grid gap-6 sm:grid-cols-2"><Field label="No. WhatsApp Aktif"><Input type="tel" inputMode="numeric" value={form.whatsapp} onChange={(e) => setField('whatsapp', e.target.value)} placeholder="0812xxxx" /></Field><Field label="Entitas / Organisasi"><Input value={form.company} onChange={(e) => setField('company', e.target.value)} placeholder="Nama Perusahaan (Opsional)" /></Field></div>
                      <div className="grid gap-6 sm:grid-cols-2">
                        <Field label="Fokus Layanan"><Select value={form.service_interest} onChange={(e) => setField('service_interest', e.target.value)}><option value="" disabled>Pilih Konsentrasi</option>{SERVICE_INTEREST_OPTIONS.map((s) => (<option key={s} value={s}>{s}</option>))}</Select></Field>
                        <Field label="Proyeksi Anggaran"><Select value={form.budget_range} onChange={(e) => setField('budget_range', e.target.value)}><option value="" disabled>Pilih Rentang</option>{BUDGET_OPTIONS.map((b) => (<option key={b} value={b}>{b}</option>))}</Select></Field>
                      </div>
                      <Field label="Spesifikasi Proyek" required error={errors.message}><Textarea rows={6} value={form.message} onChange={(e) => setField('message', e.target.value)} placeholder="Deskripsikan fitur, target rilis, dan skala proyek Anda..." /></Field>
                      <Button type="submit" size="lg" className="w-full" loading={submitting} icon={submitting ? undefined : Send}>{submitting ? 'Memproses Data...' : 'Kirim Brief Proyek'}</Button>
                    </fieldset>
                  </form>
                )}
              </GlassCard>
            </Reveal>
          </div>
        </div>
      </section>
    </>
  );
};
